CREATE TABLE IF NOT EXISTS pitlane.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,quote_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('unit','pilot')),state text NOT NULL,amount_cents bigint NOT NULL CHECK(amount_cents>=0),settled_cents bigint NOT NULL DEFAULT 0,refunded_cents bigint NOT NULL DEFAULT 0 CHECK(refunded_cents>=0 AND refunded_cents<=settled_cents),provider_id text UNIQUE,capture_before timestamptz,delivered_version_id uuid REFERENCES pitlane.receipt_versions(id),summary_artifact_id uuid REFERENCES pitlane.artifacts(id),review_minutes integer CHECK(review_minutes BETWEEN 0 AND 45),initial_units integer NOT NULL DEFAULT 1 CHECK(initial_units BETWEEN 1 AND 5),retest_granted boolean NOT NULL DEFAULT false,hold_until timestamptz NOT NULL DEFAULT now()+interval '10 minutes',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(quote_id,tenant_id,project_id) REFERENCES pitlane.quotes(id,tenant_id,project_id),UNIQUE(quote_id),UNIQUE(id,tenant_id,project_id));
CREATE TABLE IF NOT EXISTS pitlane.payment_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,order_id uuid NOT NULL REFERENCES pitlane.orders,business_key text NOT NULL UNIQUE,operation text NOT NULL CHECK(operation IN('authorize','capture','cancel','refund','reconcile')),amount_cents bigint,attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,completed_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pitlane.payment_inbox(event_id text PRIMARY KEY,provider_account text NOT NULL,origin text NOT NULL CHECK(origin IN('sandbox','live')),event_type text NOT NULL,payload jsonb NOT NULL,processed_at timestamptz,received_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE pitlane.orders ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS billing_read ON pitlane.orders;
CREATE POLICY billing_read ON pitlane.orders FOR SELECT USING(pitlane.can_billing(tenant_id));
GRANT SELECT ON pitlane.orders TO pitlane_web;
